import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

for r in range(2, 5):
    h = vws.cell(row=r, column=8).value

    if h is None or (isinstance(h, str) and h.strip() == ""):
        result = "No"
    elif isinstance(h, str):
        s = h.strip()
        if s == "N/A":
            result = "N/A"
        elif s == "Yes":
            result = "Yes"
        else:
            result = "No"
    elif isinstance(h, (datetime, date)):
        result = "Yes"
    elif isinstance(h, (int, float)) and not isinstance(h, bool):
        result = "Yes" if h > 0 else "No"
    else:
        result = "No"

    ws.cell(row=r, column=10).value = result
    print(r, repr(h), "->", result)

wb.save(OUT)
